mapper.select:
SELECT m.*, a.local_login_id 
FROM member m
JOIN member_auth a ON m.member_code = a.member_code
WHERE a.local_login_id = #{id} 
  AND m.name = #{name} 
  AND m.email = #{email} 
  AND a.login_type = 'LOCAL'

mapper.update:
UPDATE member_auth 
SET local_password = #{password}
WHERE member_code = #{memberCode} 
  AND login_type = 'LOCAL'
